        assert_eq!(c.put(3, "c"), Some((2, "b")));
        assert_eq!(c.keys_mru(), vec![3, 1]);
        assert_eq!(c.get(&2), None);
        assert_eq!(c.len(), 2);
    }

    #[test]
    fn update_refreshes_recency() {
        let mut c = LruCache::new(2);
        c.put("x".to_string(), 1);
        c.put("y".to_string(), 2);
        assert_eq!(c.put("x".to_string(), 10), None);
        assert_eq!(c.put("z".to_string(), 3), Some(("y".to_string(), 2)));
        assert_eq!(c.get(&"x".to_string()), Some(&10));
    }

    #[test]
    fn peek_does_not_touch() {
        let mut c = LruCache::new(2);
        c.put(1, 1);
        c.put(2, 2);
        assert_eq!(c.peek(&1), Some(&1));
        assert_eq!(c.put(3, 3), Some((1, 1)));
        assert_eq!(c.peek(&9), None);
    }

    #[test]
    fn zero_capacity() {
        let mut c: LruCache<i32, i32> = LruCache::new(0);
        assert_eq!(c.put(1, 1), Some((1, 1)));
        assert_eq!(c.len(), 0);
        assert_eq!(c.get(&1), None);
        assert!(c.keys_mru().is_empty());
    }

    #[test]
    fn many_operations() {
        let mut c = LruCache::new(3);
        for i in 0..1000 {
            c.put(i, i * 2);
            if i >= 1 {
                assert_eq!(c.get(&(i - 1)), Some(&((i - 1) * 2)));
            }
        }
        assert_eq!(c.keys_mru(), vec![998, 999, 997]);
        assert_eq!(c.len(), 3);
    }
}

